import{z as A,x as B,o as l,c as d,q as o,j as i,D as r,d as E,s,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"调平传感器与空气规","description":"","frontmatter":{"title":"调平传感器与空气规","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/level-sensor-air-gauge.md","filePath":"litho/level-sensor-air-gauge.md","lastUpdated":1791063341000}'),p={name:"litho/level-sensor-air-gauge.md"};function h(m,a,u,f,D,g){const t=B("Mermaid");return l(),d("div",null,[a[2]||(a[2]=o('<h1 id="调平传感器与空气规" tabindex="-1">调平传感器与空气规 <a class="header-anchor" href="#调平传感器与空气规" aria-label="Permalink to &quot;调平传感器与空气规&quot;">​</a></h1><div class="epigraph"><p>晶圆不是平面。调平要在扫描前把局部高度收进焦深；空气规用间隙气流测距，光学高度计看的是另一套反射。</p><footer>—— 对照 level sensor / air gauge；[焦深](/litho/depth-of-focus)、[Focus drilling](/litho/focus-drilling)</footer></div><p><a href="/litho/interferometer-vs-encoder">上一课</a>钉住 XY。缺口是 Z 与倾角：焦深在高 NA 下只有几十纳米量级，形貌必须测。本课钉调平与空气规，焦点伺服细节下一课。数量级先摆出来：按 \\(k_2\\lambda/\\mathrm{NA}^2\\) 取 \\(k_2\\approx0.5\\)，NA=1.35 时焦深约 50 nm，而片内台阶、CMP 凹陷、晶圆翘曲都是几十到几百纳米——不测地形，焦深一半以上直接送掉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>未调平的片：场内一侧在焦、一侧糊。光学高度计受薄膜栈反射率骗（假高度）；空气规近乎接触气隙，受气孔堵塞和表面多孔骗。只用一种，CDU 会在特定层上爆。</p><p>展开说：光学高度计的光要穿过或反射自整叠膜，BARC、氮化硅、多晶硅的折射率与厚度都进读数，透明膜的双界面反射混在一起，读数是各界面反射的加权和——换一层膜，同一位置读出不同的「高度」，这就是按层出现的假高度，与 <a href="/litho/topography-reflection">薄膜反射</a>一课直接同源。空气规不碰光学常数，但气流是它唯一的信息来源：喷嘴被颗粒堵了半个孔、多孔低 k 把气漏走、表面斜率把流量曲线带偏，都变成假距离；它的气隙是开放的，测量本身还可能扰动表面颗粒。两者的欺骗源正交——一个怕光学栈，一个怕气流路径——这正是互校的价值。</p><p><span class="marginnote">术语翻译：空气规（air gauge）就是「用气流当尺子」——喷嘴对着表面吹气，间隙越小气流越难泄走，读流量或压力就能反推出距离。它不接触表面，也不管材料是什么颜色，只认缝隙对气流的阻碍。</span></p>',7)),(l(),i(n,null,{default:r(()=>[s(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20LR%0A%20%20OPT%5B%22%E5%85%89%E5%AD%A6%E9%AB%98%E5%BA%A6%E8%AE%A1%22%5D%20--%3E%20F1%5B%22%E8%96%84%E8%86%9C%E6%A0%88%E5%8F%8D%E5%B0%84%E6%B7%B7%E5%90%88%20%E2%86%92%20%E5%81%87%E9%AB%98%E5%BA%A6%22%5D%0A%20%20FILM%5B%22%E6%8D%A2%E8%86%9C%E6%A0%88%20%2F%20%E9%80%8F%E6%98%8E%E8%86%9C%E5%8F%8C%E7%95%8C%E9%9D%A2%22%5D%20--%3E%20F1%0A%20%20AG%5B%22%E7%A9%BA%E6%B0%94%E8%A7%84%22%5D%20--%3E%20F2%5B%22%E5%96%B7%E5%98%B4%E5%A0%B5%E5%A1%9E%20%2F%20%E5%A4%9A%E5%AD%94%E6%BC%8F%E6%B0%94%20%E2%86%92%20%E5%81%87%E8%B7%9D%E7%A6%BB%22%5D%0A%20%20F1%20--%3E%20X%5B%22%E5%90%8C%E4%B8%80%E5%8F%82%E8%80%83%E7%89%87%E4%B8%8A%E4%BA%92%E6%A0%A1%3A%20%E8%B0%81%E6%92%92%E8%B0%8E%E5%BD%93%E5%9C%BA%E7%8E%B0%E5%BD%A2%22%5D%0A%20%20F2%20--%3E%20X%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：光学高度计读透明膜，像隔着起雾的两层玻璃找桌面高度——上下两个界面都反光，读数是两层影像按亮度加权的混合。膜一换、权重就变，「桌面」就平白挪了位置，而桌子根本没动。")],-1)),a[4]||(a[4]=e("h2",{id:"方法",tabindex:"-1"},[E("方法 "),e("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),a[5]||(a[5]=e("p",null,"扫描前测绘高度图，拟合平移+倾角，扫描中跟踪。空气规沿狭缝或多点。与浸没头的水膜厚度耦合：气隙测量不能破坏液膜。标定用已知台阶片。",-1)),a[6]||(a[6]=e("p",null,"具体顺序：曝光前沿扫描带采高度图，至少三点拟合活塞与倾角，残差图交给下一课的焦点伺服；狭缝上多个传感器要互相配准，配准漂移会伪装成场内倾斜。标定用已知台阶片，台阶值可追溯，周期并入机台校准循环；光学与空气规在同一参考片上比对，谁撒谎当场现形。浸没机台上调平在液膜铺开之前完成，测量路径避开浸没头，防止气隙扰动水膜、或反过来被水膜扰动。",-1)),(l(),i(n,null,{default:r(()=>[s(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAP%5B%22%E9%AB%98%E5%BA%A6%E5%9B%BE%22%5D%20--%3E%20FIT%5B%22%E5%B9%B3%E7%A7%BB%2B%E5%80%BE%E8%A7%92%22%5D%0A%20%20AG%5B%22%E7%A9%BA%E6%B0%94%E8%A7%84%22%5D%20--%3E%20MAP%0A%20%20OPT%5B%22%E5%85%89%E5%AD%A6%E9%AB%98%E5%BA%A6%22%5D%20--%3E%20MAP%0A%20%20FIT%20--%3E%20SCAN%5B%22%E6%89%AB%E6%8F%8F%E8%B7%9F%E7%84%A6%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">空气规在真空 EUV 上不是同一硬件。本课默认浸没/干式 DUV 气隙；EUV 用光学或电容一类，后课 EUV 再点。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>气隙流量或压力与距离近乎单调，带宽高、对光学常数不敏感。光学测距带宽可以更高、不占机械间隙，但 \\(n\\)、\\(k\\) 变了读数就漂——薄膜课的直接后果。</p><p>再补一层：空气规的本质是通过隙缝的流导，压力或流量对距离的灵敏度在小间隙端最陡，所以它天生适合纳米级读数，代价是读数对「一切影响流导的东西」都敏感，不只是距离。光学高度计走三角法或共焦法，带宽高、不占机械空间，但读数永远是膜的相位与振幅的混合体；胶与 BARC 的工艺变更会整体搬移假高度偏置，所以每次换膜栈都要重新配准。两种传感器的带宽对扫描都够用，瓶颈反而在扫描速度对空间采样的限制——采样不足会把高频地形混叠进焦点图，那不是传感器错，是采样律错。</p><p><span class="marginnote">常见误区：采样不足时，高频地形会「混叠」成缓慢起伏的假倾斜，看着像调平没做好，其实是采样律错了——沿扫描带多采几个点，常常比换一台更贵的传感器管用。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课把高度图接到焦点传感与形貌的动态跟踪，不只是曝光前一张图。还有一条边界：平移+倾角只吃掉地形的一阶量，CMP 凹陷与碟形这类片内残余形貌要靠焦点图逐点补偿；晶圆本身的翘曲与吸附应力是另一层账（<a href="/litho/wafer-distortion-stress">晶圆应力与畸变</a>），不要与传感器误差混算。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>调平是焦深预算的测量前置，几十纳米的焦深等不起。</li><li>空气规与光学高度计欺骗源不同，要互校。</li><li>出处：DOF 课；level sensor 通识。</li></ul>',9))])}const C=A(p,[["render",h]]);export{c as __pageData,C as default};
